import{_ as t,o,c as d,a2 as r}from"./chunks/framework.sc8Z_ZE3.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"start/troubleshooting.md","filePath":"start/troubleshooting.md"}'),a={name:"start/troubleshooting.md"};function n(s,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Common problems and their fixes. If yours is not here, see <a href="/docs/contribute/report">Report a bug</a>.</p><h2 id="installing-with-docker-compose" tabindex="-1">Installing with Docker Compose <a class="header-anchor" href="#installing-with-docker-compose" aria-label="Permalink to &quot;Installing with Docker Compose&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message or sign</th><th>Cause and fix</th></tr></thead><tbody><tr><td><code>required variable LLM_PROVIDER is missing</code></td><td><code>.env</code> is missing or no model block is filled in. See <a href="/docs/install/docker#steps">Docker Compose</a>.</td></tr><tr><td><code>startup.llm_provider_unsupported</code> in the log</td><td><code>LLM_PROVIDER</code> takes <code>anthropic</code>, <code>openai</code>, <code>bedrock</code> or <code>openrouter</code>. Add other providers later under <strong>Admin › Models › Providers</strong>.</td></tr><tr><td><code>port is already allocated</code></td><td>Port 8000 is taken. Set <code>OCTRYX_PORT=8080</code> in <code>.env</code>.</td></tr><tr><td>No &quot;setup code&quot; in the log</td><td>The api is still starting: <code>docker compose logs -f api</code>.</td></tr><tr><td>Sign-in returns to the login page without an error</td><td>The browser drops secure cookies on plain http. Use <code>localhost</code>, not the IP address.</td></tr><tr><td>Chat: <code>authentication_error</code> or an invalid key</td><td>The model key is wrong or revoked. Fix it under <strong>Admin › Models</strong>.</td></tr><tr><td>Bedrock: <code>ExpiredToken</code> or <code>AccessDenied</code></td><td>The AWS keys expired. Export them again, then <code>docker compose up -d</code>.</td></tr><tr><td>Chat: model not found</td><td>The model is not available to your key or region. Change <code>AGENT_DEFAULT_MODEL</code> or <code>AWS_REGION</code>.</td></tr><tr><td>Changing <code>.env</code> has no effect</td><td><code>.env</code> is read on the first start only. Change model access under <strong>Admin › Models</strong>.</td></tr><tr><td>&quot;has no price – costs are not counted&quot;</td><td>A notice only. Add the price under <strong>Admin › Models › Catalog</strong>.</td></tr></tbody></table><h2 id="installing-on-kubernetes" tabindex="-1">Installing on Kubernetes <a class="header-anchor" href="#installing-on-kubernetes" aria-label="Permalink to &quot;Installing on Kubernetes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message or sign</th><th>Cause and fix</th></tr></thead><tbody><tr><td><code>existingSecret is required</code>, <code>host is required</code></td><td>The value is missing in your values file.</td></tr><tr><td>Pod or volume <code>Pending</code></td><td>No default StorageClass. Set <code>persistence.storageClass</code>.</td></tr><tr><td>The <code>migrate</code> init container keeps restarting</td><td>The database is unreachable, or the password does not match. Check its log.</td></tr><tr><td>Large uploads break off</td><td>The ingress body limit is too small.</td></tr><tr><td>Knowledge says <code>needs_configuration</code></td><td>Set the object store&#39;s endpoint and bucket. See <a href="/docs/install/knowledge-storage">Knowledge storage</a>.</td></tr></tbody></table><h2 id="the-launcher" tabindex="-1">The launcher <a class="header-anchor" href="#the-launcher" aria-label="Permalink to &quot;The launcher&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sign</th><th>Cause and fix</th></tr></thead><tbody><tr><td>Seat &quot;not logged in&quot; or &quot;login expired&quot;</td><td>Run <code>octryx-claude login --seat</code> again.</td></tr><tr><td>Seat &quot;limit reached&quot;</td><td>Your subscription&#39;s limit. A running run goes on with a company model of the same class and returns to the seat after the reset (<a href="/docs/concepts/workspaces#seats-and-the-governed-route">Seats</a>); if the Workspace admits none, it pauses until then. Work held on the agent board is handed over to a colleague instead.</td></tr><tr><td><code>needs_configuration: no Claude model admitted and seat not allowed</code></td><td>The Workspace allows no Claude model and no seat. Ask a Workspace admin.</td></tr><tr><td><code>seat_session_expired</code></td><td>A seat session is valid for 12 hours. Start a new session.</td></tr><tr><td>Sign-in renewal fails</td><td>Run <code>octryx-claude login</code> again.</td></tr><tr><td>The installer says Python has no venv</td><td>Install <code>python3-venv</code> (Debian, Ubuntu).</td></tr><tr><td><code>native_windows_unsupported</code></td><td>Native Windows is not supported. Use WSL2.</td></tr><tr><td>Claude Code exits at start because its sandbox is unavailable</td><td>The launcher requires Claude Code&#39;s sandbox. Install what your system needs for it; see Claude Code&#39;s documentation.</td></tr><tr><td>A self-update failed</td><td>Only a warning; the old version keeps working. A failed version is retried after an hour; one that never comes up healthy is rolled back and blocked for 24 hours. <code>OCTRYX_CLAUDE_AUTO_UPDATE=0</code> turns updates off.</td></tr><tr><td>A run card shows <strong>Follow-up not started</strong>, or a run is refused with &quot;No device yet&quot;</td><td>The triage is done, but its follow-up workflow builds and tests code, and that runs only on a paired machine. Follow <strong>Pair Claude Code with the launcher</strong> (<strong>Agents › Install octryx-claude</strong>), enable a device folder, then start the workflow again. See <a href="/docs/start/first-run#_6-connect-your-machine">First run</a>.</td></tr><tr><td><code>device_folder_not_accessible</code> when adding a folder or before a job</td><td>The device service cannot read the folder, for example macOS Desktop or Documents. Use another folder, or give the service access. <code>device status</code> shows each folder&#39;s access.</td></tr></tbody></table><h2 id="in-the-app" tabindex="-1">In the app <a class="header-anchor" href="#in-the-app" aria-label="Permalink to &quot;In the app&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sign</th><th>Cause and fix</th></tr></thead><tbody><tr><td>Search says &quot;Choose a workspace&quot;</td><td>Pick a Workspace with the icon at the top of the left bar.</td></tr><tr><td>An MCP server&#39;s tools do not appear</td><td>A server does nothing until it is allowed in the Workspace. See <a href="/docs/connections/mcp">MCP servers</a>.</td></tr><tr><td>A connection shows <strong>Failing</strong></td><td>Open it, then <strong>Test</strong> for the reason. See <a href="/docs/connections/">Connections</a>.</td></tr><tr><td>A run pauses with &quot;Nothing was counted against the agent&quot;</td><td>The platform could not attribute a test result; see <a href="/docs/concepts/evidence">Evidence and checks</a>.</td></tr></tbody></table>',10)])])}const p=t(a,[["render",n]]);export{g as __pageData,p as default};
